#nullable enable // autogenerated

using MVZ2Logic.Artifacts;
using PVZEngine.Timing;

namespace MVZ2.Vanilla.Artifacts
{
    public static class VanillaArtifactExt
    {
        public static bool RunAndPassedOneSecond(this Artifact artifact)
        {
            return RunAndPassedSecond(artifact, 1f);
        }
        public static bool RunAndPassedSecond(this Artifact artifact, float seconds)
        {
            var secondTimer = artifact.GetSecondTimer();
            if (secondTimer == null)
            {
                secondTimer = TimerHelper.NewSecondTimer(seconds);
                artifact.SetSecondTimer(secondTimer);
            }

            if (secondTimer.RunToExpired())
            {
                secondTimer.ResetSeconds(seconds);
                return true;
            }
            return false;
        }
    }
}
